/*
 * A301930  G.f. A(x,y) satisfies: A(x,y) = x * (1 + y*A(x,y)*A'(x,y)) / (1 +
 *          A(x,y)*A'(x,y)), where A'(x,y) = d/dx A(x,y).
 * https://oeis.org/A301930
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, tabl
 * Formula:   a(n) is the flattened row‑major enumeration of the *
 *            coefficients T(r,c) of the triangle defined by the generating *
 *            function * A(x,y) = Σ_{r≥1} Σ_{c=0}^{r-1} T(r,c) x^r y^c *
 *            satisfying A = x·(1 + y·A·A') / (1 + A·A'), where A' = dA/dx. *
 *            * The triangle is generated by * A_1(y) = 1 , B_1(y) = 1...
 * Range:     i8 n <= 10, i16 n <= 22, i32 n <= 49, i64 n <= 140,
 *            i128 n <= 388, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>   /* malloc, realloc, free, calloc */

seq_t a(idx_t n)
{
    /* static state for memoisation -------------------------------------- */
    static seq_t **A = NULL;            /* array of rows of A */
    static seq_t **B = NULL;            /* array of rows of B */
    static idx_t rows_cap = 0;          /* capacity of A,B pointer arrays */
    static idx_t rows_used = 0;         /* number of rows already computed   */

    static seq_t *flat = NULL;          /* flattened sequence */
    static idx_t flat_cap = 0;          /* capacity of flat array  */
    static idx_t flat_len = 0;          /* number of elements stored */

    /* --------------------------------------------------- compute needed rows */
    /* find minimal r such that r*(r+1)/2 >= n */
    idx_t r_needed = 0;
    while ( r_needed * (r_needed + 1) / 2 < n )
        ++r_needed;

    /* allocate pointer arrays if necessary */
    if (rows_used < r_needed) {
        idx_t new_cap = rows_cap ? rows_cap : 1;
        while (new_cap <= r_needed) new_cap <<= 1;
        if (new_cap != rows_cap) {
            seq_t **tmpA = (seq_t**)realloc(A, (new_cap + 1) * sizeof(seq_t*));
            seq_t **tmpB = (seq_t**)realloc(B, (new_cap + 1) * sizeof(seq_t*));
            if (!tmpA || !tmpB) { /* allocation failed – abort */
                return 0;
            }
            A = tmpA; B = tmpB;
            rows_cap = new_cap;
        }

        /* compute new rows ---------------------------------------------- */
        for (idx_t r = rows_used + 1; r <= r_needed; ++r) {
            /* allocate and zero row arrays */
            A[r] = (seq_t*)calloc((size_t)r, sizeof(seq_t));
            B[r] = (seq_t*)calloc((size_t)r, sizeof(seq_t));
            if (!A[r] || !B[r]) return 0;   /* allocation failed */

            if (r == 1) {                    /* base case */
                A[1][0] = (seq_t)1;
                B[1][0] = (seq_t)1;
            } else {
                /* ----- compute A[r] ------------------------------------ */
                /* temporary array for the convolution sum */
                seq_t *sumA = (seq_t*)calloc((size_t)r, sizeof(seq_t));
                for (idx_t m = 1; m < r; ++m) {
                    seq_t *Am   = A[m];
                    seq_t *Bnr  = B[r - m];
                    size_t lenAm   = (size_t)m;
                    size_t lenBnr  = (size_t)(r - m);
                    for (size_t i = 0; i < lenAm; ++i) {
                        seq_t a_val = Am[i];
                        for (size_t j = 0; j < lenBnr; ++j) {
                            sumA[i + j] += a_val * Bnr[j];
                        }
                    }
                }
                /* A_r = -sumA + y * B_{r-1} (shifted) */
                for (idx_t i = 0; i < r; ++i) {
                    A[r][i] = -sumA[i];
                }
                seq_t *Bprev = B[r - 1];
                for (idx_t j = 0; j < r - 1; ++j) {
                    A[r][j + 1] += Bprev[j];
                }
                free(sumA);

                /* ----- compute B[r] ------------------------------------ */
                for (idx_t i = 1; i <= r; ++i) {
                    seq_t *Ai     = A[i];
                    seq_t *Aj     = A[r - i + 1];
                    size_t lenAi  = (size_t)i;
                    size_t lenAj  = (size_t)(r - i + 1);
                    seq_t coeff_i = (seq_t)i;
                    for (size_t p = 0; p < lenAi; ++p) {
                        seq_t a_val = Ai[p];
                        for (size_t q = 0; q < lenAj; ++q) {
                            B[r][p + q] += coeff_i * a_val * Aj[q];
                        }
                    }
                }
            }

            /* ----- append the new row to the flattened sequence ------- */
            if (flat_len + r > flat_cap) {
                idx_t new_flat_cap = flat_cap ? flat_cap * 2 : r * 2;
                while (new_flat_cap < flat_len + r) new_flat_cap <<= 1;
                seq_t *tmpFlat = (seq_t*)realloc(flat, new_flat_cap * sizeof(seq_t));
                if (!tmpFlat) return 0;  /* allocation failed */
                flat = tmpFlat;
                flat_cap = new_flat_cap;
            }
            for (idx_t i = 0; i < r; ++i) {
                flat[flat_len++] = A[r][i];
            }
        }
        rows_used = r_needed;
    }

    /* --------------------------------------------------- return answer */
    return flat[n - 1];
}
